CREATE TABLE Selections (SelectionId TEXT NOT NULL PRIMARY KEY, DisplayName TEXT NOT NULL, QueryJson TEXT NOT NULL, Version INTEGER NOT NULL, CreatedUtc TEXT NOT NULL, UpdatedUtc TEXT NOT NULL);
CREATE TABLE Plans (PlanId TEXT NOT NULL PRIMARY KEY, DisplayName TEXT NOT NULL, OperatorNote TEXT NULL, Version INTEGER NOT NULL, CanonicalHash TEXT NULL, CreatedUtc TEXT NOT NULL, UpdatedUtc TEXT NOT NULL);
